  ('pack_000_introduction_to_mandarin', 'pack_000_introduction_to_mandarin', 'Introduction to Mandarin', 'Pengenalan Mandarin', 'Learn pinyin, tones, hanzi, and how this app works.', 'Kenali pinyin, nada, hanzi, dan cara kerja app ini.', 0, 'prototype', 'introduction', 'both', 1, 5, 0, 'introduction', false, 'Learn pinyin, tones, hanzi, and how this app works.', 'Kenali pinyin, nada, hanzi, dan cara kerja app ini.', '{"components":0,"hanzi":0,"words":0,"sentences":0,"patterns":0}'::jsonb, '{"intro_only":true,"creates_srs_items":false,"new_items":[],"quick_practice":[],"unlock_items":[]}'::jsonb, '{"question_types":[],"examples":[]}'::jsonb, 'pack_000_introduction_to_mandarin.json', '07a6717952a67755b31291fa31f715512bdc4bfde93826d6630d07d98a826925', true),
  ('pack_001_i_you_to_be_have', 'pack_001_i_you_to_be_have', 'I / You / To Be / Have', 'Aku / Kamu / Adalah / Punya', 'Say who you are and talk about having something.', 'Mengatakan siapa kamu dan bicara tentang punya sesuatu.', 1, 'prototype', 'identity', 'simplified', 2, 5, 1, 'standard', true, 'Say who you are and talk about having something.', 'Mengatakan siapa kamu dan bicara tentang punya sesuatu.', '{"components":4,"hanzi":6,"words":7,"sentences":2,"patterns":1}'::jsonb, '{"intro_only":false,"creates_srs_items":true,"new_items":["word_wo","word_ni","word_shi","word_you_have","word_meiyou","word_bu","word_hao"],"quick_practice":[{"item_id":"word_wo","question_type":"meaning_choice"},{"item_id":"word_ni","question_type":"meaning_choice"},{"item_id":"word_shi","question_type":"meaning_choice"}],"unlock_items":["sentence_wo_shi_wo","sentence_wo_you"]}'::jsonb, '{"question_types":["meaning_choice","pinyin_choice","tone_choice","sentence_meaning"],"examples":[{"type":"meaning_choice","prompt":"我 means?","prompt_id":"Arti 我?","answer":"I / me","answer_id":"aku / saya"},{"type":"meaning_choice","prompt":"是 means?","prompt_id":"Arti 是?","answer":"is / am / are","answer_id":"adalah"},{"type":"fill_blank","prompt":"我__你。(I am you)","answer":"是"},{"type":"sentence_meaning","prompt":"我没有。","prompt_id":"我没有。","answer":"I don''t have it.","answer_id":"Aku tidak punya."}]}'::jsonb, 'pack_001_i_you_to_be_have.json', '344bd48664329670e7835d4256e93181b8f26052cadf0c1978f8e016f2f4ec02', true),
  ('pack_002_daily_actions', 'pack_002_daily_actions', 'Daily Actions', 'Aksi Harian', 'Use common daily verbs like go, come, see, eat, and drink.', 'Memakai kata kerja harian seperti pergi, datang, lihat, makan, dan minum.', 1, 'prototype', 'daily_actions', 'simplified', 2, 5, 2, 'standard', true, 'Use common daily verbs like go, come, see, eat, and drink.', 'Memakai kata kerja harian seperti pergi, datang, lihat, makan, dan minum.', '{"components":0,"hanzi":6,"words":6,"sentences":2,"patterns":1}'::jsonb, '{"intro_only":false,"creates_srs_items":true,"new_items":["word_qu","word_lai","word_kan","word_xiang","word_chi","word_he"],"quick_practice":[{"item_id":"word_qu","question_type":"meaning_choice"},{"item_id":"word_lai","question_type":"meaning_choice"},{"item_id":"word_kan","question_type":"meaning_choice"}],"unlock_items":["sentence_wo_qu","sentence_wo_xiang_qu"]}'::jsonb, '{"question_types":["meaning_choice","pinyin_choice","tone_choice","sentence_meaning"],"examples":[{"type":"meaning_choice","prompt":"去 means?","prompt_id":"Arti 去?","answer":"go","answer_id":"pergi"},{"type":"meaning_choice","prompt":"想 means?","prompt_id":"Arti 想?","answer":"want / miss","answer_id":"mau / kangen"},{"type":"fill_blank","prompt":"我__去。(I want to go)","answer":"想"},{"type":"sentence_meaning","prompt":"你来吗？","answer":"Are you coming?","answer_id":"Kamu datang?"}]}'::jsonb, 'pack_002_daily_actions.json', 'ae285180715f215eb0d30f48ec1b5e968573b7b7063ab509f087d79505907354', true),
