  ('pack_004_time_routine', 'pack_004_time_routine', 'Time & Routine', 'Waktu & Rutinitas', 'Talk about today, tomorrow, now, and simple routines.', 'Bicara tentang hari ini, besok, sekarang, dan rutinitas sederhana.', 1, 'prototype', 'time_routine', 'simplified', 2, 5, 4, 'standard', true, 'Talk about today, tomorrow, now, and simple routines.', 'Bicara tentang hari ini, besok, sekarang, dan rutinitas sederhana.', '{"components":0,"hanzi":5,"words":5,"sentences":2,"patterns":1}'::jsonb, '{"intro_only":false,"creates_srs_items":true,"new_items":["word_jintian","word_mingtian","word_xianzai","word_meitian","word_zao"],"quick_practice":[{"item_id":"word_jintian","question_type":"meaning_choice"},{"item_id":"word_mingtian","question_type":"meaning_choice"},{"item_id":"word_xianzai","question_type":"meaning_choice"}],"unlock_items":["sentence_jintian_wo_qu","sentence_xianzai_wo_kan"]}'::jsonb, '{"question_types":["meaning_choice","pinyin_choice","tone_choice","sentence_meaning"],"examples":[{"type":"meaning_choice","prompt":"今天 means?","prompt_id":"Arti 今天?","answer":"today","answer_id":"hari ini"},{"type":"meaning_choice","prompt":"明天 means?","prompt_id":"Arti 明天?","answer":"tomorrow","answer_id":"besok"},{"type":"fill_blank","prompt":"__我去。(Today I go)","answer":"今天"},{"type":"sentence_meaning","prompt":"现在你好吗？","answer":"How are you now?","answer_id":"Sekarang kamu baik?"}]}'::jsonb, 'pack_004_time_routine.json', 'bf492b6fc93e8cd54638c498d87ace0b76d1bf0d400d00d7b624a73963966882', true),
  ('pack_005_location_movement', 'pack_005_location_movement', 'Location & Movement', 'Lokasi & Gerakan', 'Say where you are and where you go.', 'Mengatakan kamu ada di mana dan pergi ke mana.', 1, 'prototype', 'location_movement', 'simplified', 2, 5, 5, 'standard', true, 'Say where you are and where you go.', 'Mengatakan kamu ada di mana dan pergi ke mana.', '{"components":0,"hanzi":6,"words":6,"sentences":2,"patterns":1}'::jsonb, '{"intro_only":false,"creates_srs_items":true,"new_items":["word_zai_location","word_zheli","word_nali_there","word_jia","word_xuexiao","word_huijia"],"quick_practice":[{"item_id":"word_zai_location","question_type":"meaning_choice"},{"item_id":"word_zheli","question_type":"meaning_choice"},{"item_id":"word_nali_there","question_type":"meaning_choice"}],"unlock_items":["sentence_wo_zai_jia","sentence_wo_qu_xuexiao"]}'::jsonb, '{"question_types":["meaning_choice","pinyin_choice","tone_choice","sentence_meaning"],"examples":[{"type":"meaning_choice","prompt":"家 means?","prompt_id":"Arti 家?","answer":"home","answer_id":"rumah"},{"type":"meaning_choice","prompt":"回家 means?","prompt_id":"Arti 回家?","answer":"go home","answer_id":"pulang"},{"type":"fill_blank","prompt":"我__家。(I am at home)","answer":"在"},{"type":"sentence_meaning","prompt":"你在哪里？","answer":"Where are you?","answer_id":"Kamu di mana?"}]}'::jsonb, 'pack_005_location_movement.json', 'cb3b278b51b6a31245cb9605b5eb543720c4f9c5e9f6efd0dc090776965d332d', true),
  ('pack_006_eating_buying', 'pack_006_eating_buying', 'Eating & Buying', 'Makan & Membeli', 'Say basic food, water, buy, and price questions.', 'Mengatakan makanan, air, beli, dan pertanyaan harga.', 1, 'prototype', 'eating_buying', 'simplified', 2, 5, 6, 'standard', true, 'Say basic food, water, buy, and price questions.', 'Mengatakan makanan, air, beli, dan pertanyaan harga.', '{"components":0,"hanzi":6,"words":6,"sentences":2,"patterns":1}'::jsonb, '{"intro_only":false,"creates_srs_items":true,"new_items":["word_mai_buy","word_qian","word_duoshao","word_duoshaoqian","word_fan","word_shui"],"quick_practice":[{"item_id":"word_mai_buy","question_type":"meaning_choice"},{"item_id":"word_qian","question_type":"meaning_choice"},{"item_id":"word_duoshao","question_type":"meaning_choice"}],"unlock_items":["sentence_wo_yao_shui","sentence_duoshaoqian"]}'::jsonb, '{"question_types":["meaning_choice","pinyin_choice","tone_choice","sentence_meaning"],"examples":[{"type":"meaning_choice","prompt":"饭 means?","prompt_id":"Arti 饭?","answer":"rice / meal","answer_id":"nasi / makan"},{"type":"meaning_choice","prompt":"水 means?","prompt_id":"Arti 水?","answer":"water","answer_id":"air"},{"type":"fill_blank","prompt":"我吃__。(I eat rice)","answer":"饭"},{"type":"sentence_meaning","prompt":"多少钱？","answer":"How much?","answer_id":"Berapa harganya?"}]}'::jsonb, 'pack_006_eating_buying.json', 'fd9b6bd1825828dff125573b2e056b49c70dc140cdb3261c618f8545beebbd85', true),
  ('pack_007_people_family', 'pack_007_people_family', 'People & Family', 'Orang & Keluarga', 'Talk about he, she, we, friends, and family.', 'Bicara tentang dia, kami/kita, teman, dan keluarga.', 1, 'prototype', 'people_family', 'simplified', 2, 5, 7, 'standard', true, 'Talk about he, she, we, friends, and family.', 'Bicara tentang dia, kami/kita, teman, dan keluarga.', '{"components":0,"hanzi":7,"words":6,"sentences":2,"patterns":1}'::jsonb, '{"intro_only":false,"creates_srs_items":true,"new_items":["word_ta_he","word_ta_she","word_women","word_pengyou","word_mama","word_baba"],"quick_practice":[{"item_id":"word_ta_he","question_type":"meaning_choice"},{"item_id":"word_ta_she","question_type":"meaning_choice"},{"item_id":"word_women","question_type":"meaning_choice"}],"unlock_items":["sentence_ta_shi_pengyou","sentence_women_shi_jiaren"]}'::jsonb, '{"question_types":["meaning_choice","pinyin_choice","tone_choice","sentence_meaning"],"examples":[{"type":"meaning_choice","prompt":"朋友 means?","prompt_id":"Arti 朋友?","answer":"friend","answer_id":"teman"},{"type":"meaning_choice","prompt":"我们 means?","prompt_id":"Arti 我们?","answer":"we / us","answer_id":"kami / kita"},{"type":"fill_blank","prompt":"他是我__。(He is my friend)","answer":"朋友"},{"type":"sentence_meaning","prompt":"她在家吗？","answer":"Is she at home?","answer_id":"Dia di rumah?"}]}'::jsonb, 'pack_007_people_family.json', '48235b123c0f5efe18d57136779a1c076fb33c756993ad2117009e4f1d7cc2ff', true),
