  ('pack_009_basic_opinions', 'pack_009_basic_opinions', 'Basic Opinions', 'Opini Dasar', 'Say what you like, think, and whether something is okay.', 'Mengatakan apa yang kamu suka, pikirkan, dan apakah sesuatu oke.', 1, 'prototype', 'opinions', 'simplified', 2, 5, 9, 'standard', true, 'Say what you like, think, and whether something is okay.', 'Mengatakan apa yang kamu suka, pikirkan, dan apakah sesuatu oke.', '{"components":0,"hanzi":5,"words":6,"sentences":2,"patterns":1}'::jsonb, '{"intro_only":false,"creates_srs_items":true,"new_items":["word_xihuan","word_bu_xihuan","word_juede","word_keyi","word_bukeyi","word_haode"],"quick_practice":[{"item_id":"word_xihuan","question_type":"meaning_choice"},{"item_id":"word_bu_xihuan","question_type":"meaning_choice"},{"item_id":"word_juede","question_type":"meaning_choice"}],"unlock_items":["sentence_wo_xihuan_shui","sentence_wo_juede_keyi"]}'::jsonb, '{"question_types":["meaning_choice","pinyin_choice","tone_choice","sentence_meaning"],"examples":[{"type":"meaning_choice","prompt":"喜欢 means?","prompt_id":"Arti 喜欢?","answer":"like","answer_id":"suka"},{"type":"meaning_choice","prompt":"可以 means?","prompt_id":"Arti 可以?","answer":"can / may","answer_id":"boleh / bisa"},{"type":"fill_blank","prompt":"我__水。(I like water)","answer":"喜欢"},{"type":"sentence_meaning","prompt":"我觉得可以。","answer":"I think it is okay.","answer_id":"Aku rasa boleh."}]}'::jsonb, 'pack_009_basic_opinions.json', 'bfdf9fccf86aec7ecd6442b491b1724ba40d26e4340ad4275703589d93301122', true),
