  ('word_duoshao', '多少', '多少', 'how much / how many', 'berapa', array['how much / how many']::text[], array['berapa']::text[], array[]::text[], array[]::text[], 'duō shǎo', 'duo1 shao3', '[{"hanzi":"多","text":"duō","tone":1},{"hanzi":"少","text":"shǎo","tone":3}]'::jsonb, '1-3', 'question word', '多 much + 少 little — *how much / how many*, asking the amount between the two.', '多 banyak + 少 sedikit — *berapa*, nanya jumlah di antara banyak dan sedikit.', null, null, null, null, null, array['[object Object]']::text[], 3, array['shopping']::text[], true, true),
  ('word_duoshaoqian', '多少钱', '多少錢', 'how much money', 'berapa harganya', array['how much money']::text[], array['berapa harganya']::text[], array[]::text[], array[]::text[], 'duō shǎo qián', 'duo1 shao3 qian2', '[{"hanzi":"多","text":"duō","tone":1},{"hanzi":"少","text":"shǎo","tone":3},{"hanzi":"钱","text":"qián","tone":2}]'::jsonb, '1-3-2', 'question phrase', '多少 how much + 钱 money — "*how much does it cost*" — the most important phrase in any shop.', '多少 berapa + 钱 uang — "*berapa harganya*" — kalimat paling penting di toko.', null, null, 'Essential phrase for shopping.', 'Frasa penting untuk belanja.', null, array['[object Object]']::text[], 4, array['shopping']::text[], true, true),
  ('word_fan', '饭', '飯', 'rice / meal', 'nasi / makanan', array['rice / meal']::text[], array['nasi / makanan']::text[], array[]::text[], array[]::text[], 'fàn', 'fan4', '[{"hanzi":"饭","text":"fàn","tone":4}]'::jsonb, '4', 'noun', '*Rice* or food in general — 饭 can mean both depending on context.', '*Nasi* atau makanan secara umum — 饭 bisa berarti keduanya tergantung konteks.', null, null, '吃饭 literally means "eat rice" but is used for any meal.', '吃饭 secara harfiah berarti "makan nasi" tapi dipakai untuk semua makan.', null, array['[object Object]']::text[], 5, array['food']::text[], true, true),
