  ('word_bu_xihuan', '不喜欢', '不喜歡', 'do not like', 'tidak suka', array['do not like']::text[], array['tidak suka']::text[], array[]::text[], array[]::text[], 'bù xǐ huān', 'bu4 xi3 huan1', '[{"hanzi":"不","text":"bù","tone":4},{"hanzi":"喜","text":"xǐ","tone":3},{"hanzi":"欢","text":"huān","tone":1}]'::jsonb, '4-3-1', 'verb phrase', '不 not + 喜欢 like — *don''t like*, direct and clear.', '不 tidak + 喜欢 suka — *tidak suka*, langsung dan jelas.', null, null, null, null, null, array['[object Object]']::text[], 2, array['opinion']::text[], true, true),
