  ('word_wushi', '五十', '五十', 'fifty', 'lima puluh', array['fifty']::text[], array['lima puluh']::text[], array[]::text[], array[]::text[], 'wǔ shí', 'wu3 shi2', '[{"hanzi":"五","text":"wǔ","tone":3},{"hanzi":"十","text":"shí","tone":2}]'::jsonb, '3-2', 'number', '五 five + 十 ten — *fifty*, halfway to a hundred.', '五 lima + 十 sepuluh — *lima puluh*, setengah dari seratus.', null, null, null, null, null, array['[object Object]']::text[], 5, array['number']::text[], true, true),
  ('word_yibai', '一百', '一百', 'one hundred', 'seratus', array['one hundred']::text[], array['seratus']::text[], array[]::text[], array[]::text[], 'yì bǎi', 'yi4 bai3', '[{"hanzi":"一","text":"yì","tone":4},{"hanzi":"百","text":"bǎi","tone":3}]'::jsonb, '4-3', 'number', '一 one + 百 hundred — exactly *one hundred*.', '一 satu + 百 ratus — tepat *seratus*.', null, null, null, null, null, array['[object Object]']::text[], 6, array['number']::text[], true, true),
  ('word_duoshao_number', '多少', '多少', 'how many', 'berapa', array['how many']::text[], array['berapa']::text[], array[]::text[], array[]::text[], 'duō shǎo', 'duo1 shao3', '[{"hanzi":"多","text":"duō","tone":1},{"hanzi":"少","text":"shǎo","tone":3}]'::jsonb, '1-3', 'question word', 'Already learned — *how many*, asking the amount.', 'Sudah dipelajari — *berapa*, nanya jumlah.', null, null, null, null, null, array['[object Object]']::text[], 7, array['number', 'question']::text[], true, true),
  ('word_zuotian', '昨天', '昨天', 'yesterday', 'kemarin', array['yesterday']::text[], array['kemarin']::text[], array[]::text[], array[]::text[], 'zuó tiān', 'zuo2 tian1', '[{"hanzi":"昨","text":"zuó","tone":2},{"hanzi":"天","text":"tiān","tone":1}]'::jsonb, '2-1', 'time word', '昨 yesterday + 天 day — *yesterday*, the day just behind you.', '昨 kemarin + 天 hari — *kemarin*, hari yang baru saja lewat.', null, null, null, null, null, array['[object Object]']::text[], 1, array['time']::text[], true, true),
  ('word_xingqi', '星期', '星期', 'week', 'minggu', array['week']::text[], array['minggu']::text[], array[]::text[], array[]::text[], 'xīng qī', 'xing1 qi1', '[{"hanzi":"星","text":"xīng","tone":1},{"hanzi":"期","text":"qī","tone":1}]'::jsonb, '1-1', 'time word', '星 star + 期 period — *week*, a cycle measured by the stars.', '星 bintang + 期 periode — *minggu*, siklus yang diukur bintang.', null, null, null, null, null, array['[object Object]']::text[], 2, array['time']::text[], true, true),
  ('word_xingqiyi', '星期一', '星期一', 'Monday', 'hari Senin', array['Monday']::text[], array['hari Senin']::text[], array[]::text[], array[]::text[], 'xīng qī yī', 'xing1 qi1 yi1', '[{"hanzi":"星","text":"xīng","tone":1},{"hanzi":"期","text":"qī","tone":1},{"hanzi":"一","text":"yī","tone":1}]'::jsonb, '1-1-1', 'time word', '星期 week + 一 one — *Monday*, the first day of the week.', '星期 minggu + 一 satu — *Senin*, hari pertama dalam seminggu.', null, null, 'Days Mon–Sat use 星期 + number 1–6. Sunday is 星期日 or 星期天.', 'Hari Senin–Sabtu pakai 星期 + angka 1–6. Minggu adalah 星期日 atau 星期天.', null, array['[object Object]']::text[], 3, array['time']::text[], true, true),
  ('word_yue_month', '月', '月', 'month', 'bulan', array['month']::text[], array['bulan']::text[], array[]::text[], array[]::text[], 'yuè', 'yue4', '[{"hanzi":"月","text":"yuè","tone":4}]'::jsonb, '4', 'time word', 'One character, two meanings — *month* and *moon*, both measured by the lunar cycle.', 'Satu karakter, dua makna — *bulan* (waktu) dan *bulan* (benda), keduanya diukur dari siklus bulan.', null, null, 'Months use number + 月: 一月 Jan, 二月 Feb, etc.', 'Bulan pakai angka + 月: 一月 Jan, 二月 Feb, dst.', null, array['[object Object]']::text[], 4, array['time']::text[], true, true),
  ('word_ri_date', '日', '日', 'day / date', 'hari / tanggal', array['day / date']::text[], array['hari / tanggal']::text[], array[]::text[], array[]::text[], 'rì', 'ri4', '[{"hanzi":"日","text":"rì","tone":4}]'::jsonb, '4', 'time word', '*Day* or *date* — used formally and in dates like 三月一日 March 1st.', '*Hari* atau *tanggal* — dipakai formal dan dalam tanggal seperti 三月一日 1 Maret.', null, null, 'In dates: year 年 + month 月 + day 日.', 'Dalam tanggal: tahun 年 + bulan 月 + hari 日.', null, array['[object Object]']::text[], 5, array['time']::text[], true, true),
  ('word_jinnian', '今年', '今年', 'this year', 'tahun ini', array['this year']::text[], array['tahun ini']::text[], array[]::text[], array[]::text[], 'jīn nián', 'jin1 nian2', '[{"hanzi":"今","text":"jīn","tone":1},{"hanzi":"年","text":"nián","tone":2}]'::jsonb, '1-2', 'time word', '今 now + 年 year — *this year*, the year you''re living.', '今 sekarang + 年 tahun — *tahun ini*, tahun yang sedang dijalani.', null, null, null, null, null, array['[object Object]']::text[], 6, array['time']::text[], true, true),
  ('word_mingnian', '明年', '明年', 'next year', 'tahun depan', array['next year']::text[], array['tahun depan']::text[], array[]::text[], array[]::text[], 'míng nián', 'ming2 nian2', '[{"hanzi":"明","text":"míng","tone":2},{"hanzi":"年","text":"nián","tone":2}]'::jsonb, '2-2', 'time word', '明 bright + 年 year — *next year*, the bright year still ahead.', '明 terang + 年 tahun — *tahun depan*, tahun cerah yang masih di depan.', null, null, null, null, null, array['[object Object]']::text[], 7, array['time']::text[], true, true),
  ('word_ge', '个', '個', 'general measure word', 'kata bantu hitung umum', array['general measure word']::text[], array['kata bantu hitung umum']::text[], array[]::text[], array[]::text[], 'ge', 'ge0', '[{"hanzi":"个","text":"ge","tone":0}]'::jsonb, '0', 'measure word', 'The go-to measure word — when unsure, use *个*.', 'Kata bantu bilangan andalan — kalau ragu, pakai *个*.', null, null, '个 works for people and most objects when you''re not sure of the specific measure word.', '个 cocok untuk orang dan kebanyakan benda saat tidak yakin kata bantu bilangan yang spesifik.', null, array['[object Object]']::text[], 1, array['measure']::text[], true, true),
  ('word_yi_ge', '一个', '一個', 'one item / one person', 'satu buah / satu orang', array['one item / one person']::text[], array['satu buah / satu orang']::text[], array[]::text[], array[]::text[], 'yí ge', 'yi2 ge0', '[{"hanzi":"一","text":"yí","tone":2},{"hanzi":"个","text":"ge","tone":0}]'::jsonb, '2-0', 'measure phrase', '一 one + 个 item — *one* of something, the most basic count.', '一 satu + 个 buah — *satu* buah sesuatu, hitungan paling dasar.', null, null, null, null, null, array['[object Object]']::text[], 2, array['measure']::text[], true, true),
  ('word_liang_ge', '两个', '兩個', 'two items / two people', 'dua buah / dua orang', array['two items / two people']::text[], array['dua buah / dua orang']::text[], array[]::text[], array[]::text[], 'liǎng ge', 'liang3 ge0', '[{"hanzi":"两","text":"liǎng","tone":3},{"hanzi":"个","text":"ge","tone":0}]'::jsonb, '3-0', 'measure phrase', '两 two (for counting) + 个 — *two* of something. Use 两 not 二 before measure words.', '两 dua (untuk menghitung) + 个 — *dua* buah sesuatu. Pakai 两 bukan 二 sebelum kata bantu bilangan.', null, null, 'Use 两 (liǎng) not 二 when counting with measure words.', 'Gunakan 两 (liǎng) bukan 二 saat menghitung dengan kata bantu bilangan.', null, array['[object Object]']::text[], 3, array['measure']::text[], true, true),
