  ('word_yi_ben', '一本', '一本', 'one book', 'satu buku', array['one book']::text[], array['satu buku']::text[], array[]::text[], array[]::text[], 'yì běn', 'yi4 ben3', '[{"hanzi":"一","text":"yì","tone":4},{"hanzi":"本","text":"běn","tone":3}]'::jsonb, '4-3', 'measure phrase', '一 one + 本 book — *one book*. 本 is the specific measure for books.', '一 satu + 本 buku — *satu buku*. 本 adalah kata bantu bilangan khusus untuk buku.', null, null, null, null, null, array['[object Object]']::text[], 5, array['measure']::text[], true, true),
