  ('word_naxie', '那些', '那些', 'those', 'itu semua / beberapa itu', array['those']::text[], array['itu semua / beberapa itu']::text[], array[]::text[], array[]::text[], 'nà xiē', 'na4 xie1', '[{"hanzi":"那","text":"nà","tone":4},{"hanzi":"些","text":"xiē","tone":1}]'::jsonb, '4-1', 'pronoun', '那 that + 些 some — *those*, a group of things further away.', '那 itu + 些 beberapa — *itu semua*, sekelompok benda yang lebih jauh.', null, null, null, null, null, array['[object Object]']::text[], 7, array['demonstrative']::text[], true, true),
  ('word_mifan', '米饭', '米飯', 'cooked rice', 'nasi', array['cooked rice']::text[], array['nasi']::text[], array[]::text[], array[]::text[], 'mǐ fàn', 'mi3 fan4', '[{"hanzi":"米","text":"mǐ","tone":3},{"hanzi":"饭","text":"fàn","tone":4}]'::jsonb, '3-4', 'noun', '米 raw rice + 饭 cooked food — *cooked rice*, the staple on every table.', '米 beras mentah + 饭 makanan matang — *nasi*, makanan pokok di setiap meja.', null, null, '米饭 specifically means cooked white rice. 饭 alone can mean any meal.', '米饭 khusus berarti nasi putih matang. 饭 sendiri bisa berarti makan apapun.', null, array['[object Object]']::text[], 1, array['food']::text[], true, true),
  ('word_miantiao', '面条', '麵條', 'noodles', 'mi', array['noodles']::text[], array['mi']::text[], array[]::text[], array[]::text[], 'miàn tiáo', 'mian4 tiao2', '[{"hanzi":"面","text":"miàn","tone":4},{"hanzi":"条","text":"tiáo","tone":2}]'::jsonb, '4-2', 'noun', '面 noodle dough + 条 strip — *noodles*, long thin strips of dough.', '面 adonan mie + 条 potongan — *mie*, potongan adonan yang panjang dan tipis.', null, null, null, null, null, array['[object Object]']::text[], 2, array['food']::text[], true, true),
